use std::{ffi::OsString, fs, process::Command};

use anyhow::Context;
use clap::Parser;
use exposed::{
    domain::{
        models::{entity_ingestion::IngestionKey, entity_search::EntitySearchRequest},
        repositories::parliament_member_repository::ParliamentMemberRepo,
    },
    inbound::cli::{DataArgs, run_cli},
    outbound::ExposedDatabase,
};
use sqlx::{ConnectOptions, PgPool};
use tempfile::TempDir;

use crate::common::{
    DeclarationFunding, FundingEntry, cli_declaration_fetcher_config, cli_fetcher_config,
    cli_loader_config, funder_details, read_declaration_funding, search_entities, start_app,
};

mod common;

#[sqlx::test(migrations = "../db/migrations")]
async fn search_retains_canonical_identity_and_alias_provenance(
    pool: PgPool,
) -> anyhow::Result<()> {
    let id = uuid::Uuid::from_u128(1);
    sqlx::query!("INSERT INTO exposed.funders (id, funder_name, funder_kind) VALUES ($1, 'Northstar', 'Company')", id).execute(&pool).await?;
    for alias in ["Fletchers", "Fletchers Group"] {
        sqlx::query!(
            "INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2)",
            id,
            alias
        )
        .execute(&pool)
        .await?;
    }
    let app = start_app(exposed::inbound::http::config::ServerConfig {
        connection_string: pool.connect_options().to_url_lossy().into(),
    })
    .await?;
    let req = EntitySearchRequest::new_strict("Fletchers".into(), 10)?;
    let results = search_entities(&app, &req).await?;
    assert_eq!(results.len(), 1);
    assert_eq!(results[0]["id"], id.to_string());
    assert_eq!(results[0]["name"], "Northstar");
    assert_eq!(
        results[0]["match_source"],
        serde_json::json!({"kind": "alias", "name": "Fletchers"})
    );
    let req = EntitySearchRequest::new_strict("Northstar".into(), 10)?;
    let results = search_entities(&app, &req).await?;
    assert_eq!(results.len(), 1);
    assert_eq!(results[0]["id"], id.to_string());
    assert_eq!(
        results[0]["match_source"],
        serde_json::json!({"kind": "name"})
    );
    Ok(())
}

#[sqlx::test(migrations = "../db/migrations")]
async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new().unwrap();

    let (_file, path) = cli_fetcher_config(&tmp);
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "fetch".into(),
        "--config".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_loader_config(&tmp);
    // The process environment must override a URL in .env.
    fs::write(tmp.path().join(".env"), "DATABASE_URL=invalid-url\n").unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env("DATABASE_URL", url.as_str())
        .args(["data", "members", "load"])
        .arg("--config")
        .arg(path)
        .args(["--ingestion-key", &ingestion_key.to_string()])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );

    let url = pool.connect_options().to_url_lossy();
    let db = ExposedDatabase::new(url.as_str()).await;

    let params =
        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    let res = db.get_members_by_text_search_score(&params).await.unwrap();

    let (mp, _) = res.first().unwrap();
    assert_eq!(mp.name(), "John McDonnell".to_string());

    Ok(())
}
//! CLI coverage for the latest ingestion key and path.

use std::{
    fs,
    path::Path,
    process::{Command, Output},
    time::{Duration, SystemTime},
};

use exposed::{domain::models::entity_ingestion::IngestionKey, outbound::ExposedDataPipeline};
use tempfile::TempDir;
use uuid::Uuid;

fn run_latest(root: &Path) -> anyhow::Result<Output> {
    fs::write(root.join(".env"), "")?;
    fs::write(root.join("config.yaml"), "data_dir: ./data\n")?;
    Ok(Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(root)
        .env_remove("DATABASE_URL")
        .args(["data", "latest", "--config", "config.yaml"])
        .output()?)
}

fn stdout(output: &Output) -> &str {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::str::from_utf8(&output.stdout).unwrap()
}

fn create_run(data: &Path, key: &IngestionKey, seconds: u64) -> anyhow::Result<()> {
    ExposedDataPipeline::new_with_ingestion_key(&data.to_path_buf(), key.clone())?;
    fs::File::open(data.join(key.to_string()))?
        .set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(seconds))?;
    Ok(())
}

#[test]
fn reports_only_the_latest_key_and_absolute_run_path_without_a_database() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    let older: IngestionKey = "ffffffff-ffff-4fff-8fff-ffffffffffff".parse()?;
    let latest: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
    create_run(&data, &older, 10)?;
    create_run(&data, &latest, 20)?;
    fs::create_dir(data.join("not-an-ingestion-key"))?;
    fs::write(
        data.join(IngestionKey::default().to_string()),
        "not a directory",
    )?;

    let output = run_latest(tmp.path())?;
    let path = data.canonicalize()?.join(latest.to_string());

    assert_eq!(
        stdout(&output),
        format!("Ingestion key: {latest}\nPath: {}\n", path.display())
    );
    assert_eq!(fs::read_dir(&data)?.count(), 4);
    Ok(())
}

#[test]
fn equal_timestamps_use_the_greatest_uuid_regardless_of_creation_order() -> anyhow::Result<()> {
    let lower = IngestionKey::new(Uuid::from_u128(1));
    let higher = IngestionKey::new(Uuid::from_u128(2));
    for keys in [[&lower, &higher], [&higher, &lower]] {
        let tmp = TempDir::new()?;
        let data = tmp.path().join("data");
        for key in keys {
            create_run(&data, key, 10)?;
        }

        let output = run_latest(tmp.path())?;
        let path = data.canonicalize()?.join(higher.to_string());

        assert_eq!(
            stdout(&output),
            format!("Ingestion key: {higher}\nPath: {}\n", path.display())
        );
    }
    Ok(())
}

#[test]
fn missing_or_empty_store_has_no_runs_and_stays_unchanged() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        "No ingestion runs found.\n"
    );
    assert!(!data.exists());

    fs::create_dir(&data)?;
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        "No ingestion runs found.\n"
    );
    assert_eq!(fs::read_dir(&data)?.count(), 0);
    Ok(())
}

#[test]
fn invalid_store_path_fails_with_a_read_error() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    fs::write(tmp.path().join("data"), "not a directory")?;

    let output = run_latest(tmp.path())?;

    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    assert!(String::from_utf8_lossy(&output.stderr).contains("unable to read pipeline data"));
    Ok(())
}

